if env.user.has_group('ydod_mass_cancel_reset_wizard.group_mass_cancel_manager'):
    action = {
        'name': 'Mass Cancel / Reset Sales Orders',
        'type': 'ir.actions.act_window',
        'res_model': 'ydod.mass.cancel.wizard',
        'view_mode': 'form',
        'target': 'new',
        'context': {
            'default_model_name': 'sale.order',
            'active_ids': env.context.get('active_ids', []),
        },
    }
else:
    raise UserError(_("You are not authorized to perform mass cancel and reset operations."))

